R("pastarva", "тенджера с капак, голям тиган, широка шпатула, кухненска хартия",
  S("Сложи ориза", "Изплакни ориза@rice в цедка, докато водата стане бистра. Сложи го в тенджера с {600 мл} вода и {0.5 ч.л.} сол. Когато заври, намали на най-слабо, похлупи и вари 15 минути, без да вдигаш капака.", None, 15),
  S("Подготви рибата", "Изплакни пъстървите@trout и ги подсуши много добре с кухненска хартия отвътре и отвън. Посоли ги и ги поръси с пипер, също и в корема.",
    "Мократа риба пръска в мазнината и не хваща коричка."),
  S("Загрей маслото", "Сложи маслото@butter в голям тиган на средна към силна степен. Изчакай да се разтопи и да спре да се пени (около 1 минута)."),
  S("Пържи от първата страна", "Сложи рибите в тигана с главата в една посока. Не ги мести 5 минути, за да хване кожата златиста коричка.", None, 5),
  S("Обърни и довърши", "Обърни внимателно с широка шпатула, като придържаш с вилица. Пържи още 4–5 минути. Полей с половината лимонов сок@lemon*0.5.",
    "Готова е, когато месото до костта е бяло и се отделя лесно.", 5),
  S("Сервирай", "Сервирай рибата с ориза и резенчета от останалия лимон@lemon*0.5."),
)

R("bobnadenitsa", "тенджера, дъска, нож, цедка, дървена лъжица",
  S("Нарежи", "Обели лука@onion и го нарежи на ситни кубчета. Нарежи надениците@sausages на кръгчета около 1 см."),
  S("Запържи", "Загрей олиото@oil в тенджерата на средна степен. Пържи лука 3 минути, докато омекне. Добави наденицата и пържи още 3 минути, докато леко се зачерви по ръбовете.", None, 6),
  S("Пипер, домати и боб", "Махни тенджерата от котлона и разбъркай {1 ч.л.} червен пипер. Изсипи доматите@tomcan. Изцеди боба@beanscan в цедка, изплакни го и го добави."),
  S("Вари", "Върни на котлона, налей {1 чаша/чаша} вода и добави {1 ч.л.} чубрица. Когато заври, намали на слабо и остави да къкри 15 минути, като бъркаш понякога. Опитай и посоли.", None, 15),
)

R("guvech", "тиган, гювеч или дълбока тава с капак или фолио, дъска, нож",
  S("Нарежи всичко", "Включи фурната на 180°. Нарежи месото@porkstew на кубчета 2–3 см. Обели и нарежи картофите@potatoes на кубчета, моркова@carrot на кръгчета, лука@onion на едри парчета. Изчисти гъбите@mushrooms и ги нарежи на четвъртинки."),
  S("Запечи месото", "Загрей олиото@oil в тиган на силна степен. Сложи месото и го пържи 6–8 минути, като го обръщаш, докато покафенее от всички страни.", None, 8),
  S("Смеси в гювеча", "В гювеча изсипи месото заедно с мазнината. Добави всички зеленчуци, доматите@tomcan, изцедения грах@peascan, {2 ч.л.} сол, {1 ч.л.} червен пипер и 2 дафинови листа. Разбъркай добре."),
  S("Печи похлупено", "Налей {1 чаша/чаша} вода, похлупи с капак или фолио и пеки 60 минути.",
    "Не отваряй често: парата вътре задушава месото и то става крехко.", 60),
  S("Сгъсти соса", "Махни капака (с ръкавица, излиза пара) и пеки още 10 минути, за да се сгъсти сосът и отгоре да хване цвят.", None, 10),
)

R("lovdjiiski", "широка тенджера с капак, кухненска хартия, дъска, нож",
  S("Запечи пилето", "Подсуши бутчетата@chlegs с хартия и ги посоли. Загрей олиото@oil в широка тенджера на силна степен. Сложи пилето с кожата надолу и го пържи 4 минути, после обърни за още 4. Извади го в чиния.", None, 8),
  S("Лук и гъби", "Нарежи лука@onion на полумесеци и гъбите@mushrooms на четвъртинки. Сложи ги в мазнината от пилето и пържи 6–7 минути на средна степен, докато гъбите пуснат вода и тя изври.", None, 7),
  S("Сосът", "Добави доматите@tomcan, 2 дафинови листа, щипка пипер и {1 чаша/чаша} вода. Разбъркай и остърги кафявите петна от дъното с лъжицата: в тях е вкусът."),
  S("Задуши", "Върни пилето в тенджерата, похлупи и задуши на слаб огън 40 минути, докато месото започне да пада от костта.", None, 40),
)

